package com.fasttravel.controller;import com.fasttravel.dto.ApiResponse;import com.fasttravel.dto.AuthDTO.*;import com.fasttravel.service.AuthService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/auth") @RequiredArgsConstructor public class AuthController{private final AuthService service;@PostMapping("/login") public ApiResponse<?> login(@Valid @RequestBody LoginRequest r){return ApiResponse.ok("Đăng nhập thành công",service.login(r));}@PostMapping("/register") public ApiResponse<?> register(@Valid @RequestBody RegisterRequest r){return ApiResponse.ok("Đăng ký thành công",service.register(r));}}
